CREATE TABLE IF NOT EXISTS accounts (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, name VARCHAR(190), slug VARCHAR(190) UNIQUE, status ENUM('active','suspended','archived') DEFAULT 'active', created_at DATETIME, updated_at DATETIME);
CREATE TABLE IF NOT EXISTS users (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, email VARCHAR(190) UNIQUE, password_hash VARCHAR(255), first_name VARCHAR(100), last_name VARCHAR(100) NULL, created_at DATETIME, updated_at DATETIME);
CREATE TABLE IF NOT EXISTS projects (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, account_id BIGINT UNSIGNED, name VARCHAR(190), slug VARCHAR(190), created_at DATETIME, updated_at DATETIME, UNIQUE KEY uq_project_slug(account_id, slug));
CREATE TABLE IF NOT EXISTS bots (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, account_id BIGINT UNSIGNED, project_id BIGINT UNSIGNED, name VARCHAR(190), token_encrypted TEXT, webhook_secret VARCHAR(128), status ENUM('active','paused','disabled') DEFAULT 'active', created_at DATETIME, updated_at DATETIME);
CREATE TABLE IF NOT EXISTS processes (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, account_id BIGINT UNSIGNED, project_id BIGINT UNSIGNED, bot_id BIGINT UNSIGNED, name VARCHAR(190), slug VARCHAR(190), status ENUM('draft','published','archived') DEFAULT 'draft', active_version_id BIGINT UNSIGNED NULL, created_at DATETIME, updated_at DATETIME);
CREATE TABLE IF NOT EXISTS process_versions (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, process_id BIGINT UNSIGNED, version_number INT, status ENUM('draft','published','archived') DEFAULT 'draft', graph_json JSON, compiled_graph_json JSON NULL, graph_hash CHAR(64), validation_status ENUM('valid','invalid','warning') DEFAULT 'invalid', created_at DATETIME, updated_at DATETIME, UNIQUE KEY uq_version(process_id, version_number));
CREATE TABLE IF NOT EXISTS process_nodes (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, process_version_id BIGINT UNSIGNED, node_uuid CHAR(36), node_type VARCHAR(64), title VARCHAR(190), config_json JSON, created_at DATETIME, updated_at DATETIME, UNIQUE KEY uq_node(process_version_id, node_uuid));
CREATE TABLE IF NOT EXISTS process_edges (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, process_version_id BIGINT UNSIGNED, edge_uuid CHAR(36), source_node_uuid CHAR(36), target_node_uuid CHAR(36), condition_key VARCHAR(64) NULL, sort_order INT DEFAULT 0, created_at DATETIME, updated_at DATETIME, UNIQUE KEY uq_edge(process_version_id, edge_uuid));
CREATE TABLE IF NOT EXISTS contacts (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, account_id BIGINT UNSIGNED, project_id BIGINT UNSIGNED, bot_id BIGINT UNSIGNED, telegram_user_id BIGINT NULL, telegram_chat_id BIGINT NULL, first_name VARCHAR(190) NULL, phone VARCHAR(50) NULL, email VARCHAR(190) NULL, status ENUM('active','blocked','archived') DEFAULT 'active', contact_fields_json JSON NULL, created_at DATETIME, updated_at DATETIME);
CREATE TABLE IF NOT EXISTS chats (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, account_id BIGINT UNSIGNED, project_id BIGINT UNSIGNED, bot_id BIGINT UNSIGNED, contact_id BIGINT UNSIGNED, telegram_chat_id BIGINT, mode ENUM('auto','manual','hybrid') DEFAULT 'auto', created_at DATETIME, updated_at DATETIME);
CREATE TABLE IF NOT EXISTS chat_messages (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, chat_id BIGINT UNSIGNED, contact_id BIGINT UNSIGNED, bot_id BIGINT UNSIGNED, direction ENUM('in','out','system','operator'), message_type VARCHAR(64), text_content TEXT NULL, payload_json JSON NULL, status ENUM('sent','delivered','failed','received','read') DEFAULT 'received', created_at DATETIME, updated_at DATETIME);
CREATE TABLE IF NOT EXISTS executions (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, account_id BIGINT UNSIGNED, project_id BIGINT UNSIGNED, bot_id BIGINT UNSIGNED, process_id BIGINT UNSIGNED, process_version_id BIGINT UNSIGNED, contact_id BIGINT UNSIGNED, current_node_uuid CHAR(36) NULL, status ENUM('running','waiting','scheduled','completed','failed','cancelled') DEFAULT 'running', step_count INT DEFAULT 0, context_json JSON, started_at DATETIME, finished_at DATETIME NULL, created_at DATETIME, updated_at DATETIME);
CREATE TABLE IF NOT EXISTS execution_steps (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, execution_id BIGINT UNSIGNED, process_version_id BIGINT UNSIGNED, node_uuid CHAR(36), node_type VARCHAR(64), status ENUM('entered','completed','waiting','failed','skipped'), input_json JSON NULL, output_json JSON NULL, created_at DATETIME);
CREATE TABLE IF NOT EXISTS waiting_states (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, execution_id BIGINT UNSIGNED, contact_id BIGINT UNSIGNED, node_uuid CHAR(36), input_type VARCHAR(64), save_to_key VARCHAR(128), validation_rules_json JSON NULL, attempt_count INT DEFAULT 0, max_attempts INT DEFAULT 3, expires_at DATETIME NULL, status ENUM('active','resolved','expired','cancelled') DEFAULT 'active', created_at DATETIME, updated_at DATETIME);
CREATE TABLE IF NOT EXISTS message_templates (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, account_id BIGINT UNSIGNED, project_id BIGINT UNSIGNED NULL, name VARCHAR(190), slug VARCHAR(190), status ENUM('draft','published','archived') DEFAULT 'draft', active_version_id BIGINT UNSIGNED NULL, created_at DATETIME, updated_at DATETIME);
CREATE TABLE IF NOT EXISTS message_template_versions (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, template_id BIGINT UNSIGNED, version_number INT, payload_json JSON, status ENUM('draft','published','archived') DEFAULT 'draft', created_at DATETIME, updated_at DATETIME);
CREATE TABLE IF NOT EXISTS reusable_blocks (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, account_id BIGINT UNSIGNED, project_id BIGINT UNSIGNED NULL, name VARCHAR(190), slug VARCHAR(190), status ENUM('draft','published','archived') DEFAULT 'draft', created_at DATETIME, updated_at DATETIME);
CREATE TABLE IF NOT EXISTS reusable_block_versions (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, reusable_block_id BIGINT UNSIGNED, version_number INT, graph_json JSON, compiled_graph_json JSON NULL, input_contract_json JSON NULL, output_contract_json JSON NULL, status ENUM('draft','published','archived') DEFAULT 'draft', created_at DATETIME, updated_at DATETIME);
CREATE TABLE IF NOT EXISTS funnels (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, account_id BIGINT UNSIGNED, project_id BIGINT UNSIGNED, bot_id BIGINT UNSIGNED NULL, name VARCHAR(190), slug VARCHAR(190), status ENUM('draft','published','archived') DEFAULT 'draft', created_at DATETIME, updated_at DATETIME);
CREATE TABLE IF NOT EXISTS funnel_steps (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, funnel_id BIGINT UNSIGNED, step_code VARCHAR(128), name VARCHAR(190), step_order INT, created_at DATETIME, updated_at DATETIME);
CREATE TABLE IF NOT EXISTS funnel_entries (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, funnel_id BIGINT UNSIGNED, contact_id BIGINT UNSIGNED, current_step_id BIGINT UNSIGNED NULL, status ENUM('active','completed','dropped','archived') DEFAULT 'active', entered_at DATETIME, created_at DATETIME, updated_at DATETIME);
CREATE TABLE IF NOT EXISTS funnel_progress (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, funnel_entry_id BIGINT UNSIGNED, funnel_id BIGINT UNSIGNED, contact_id BIGINT UNSIGNED, step_id BIGINT UNSIGNED, entered_at DATETIME, exited_at DATETIME NULL, created_at DATETIME);
CREATE TABLE IF NOT EXISTS pipelines (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, account_id BIGINT UNSIGNED, project_id BIGINT UNSIGNED, name VARCHAR(190), slug VARCHAR(190), status ENUM('active','archived') DEFAULT 'active', created_at DATETIME, updated_at DATETIME);
CREATE TABLE IF NOT EXISTS pipeline_stages (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, pipeline_id BIGINT UNSIGNED, code VARCHAR(128), name VARCHAR(190), sort_order INT, is_won TINYINT(1) DEFAULT 0, is_lost TINYINT(1) DEFAULT 0, created_at DATETIME, updated_at DATETIME);
CREATE TABLE IF NOT EXISTS deals (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, account_id BIGINT UNSIGNED, project_id BIGINT UNSIGNED, contact_id BIGINT UNSIGNED, pipeline_id BIGINT UNSIGNED, stage_id BIGINT UNSIGNED, title VARCHAR(255), amount DECIMAL(18,2) NULL, status ENUM('open','won','lost','archived') DEFAULT 'open', created_at DATETIME, updated_at DATETIME);
CREATE TABLE IF NOT EXISTS marketplace_items (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, account_id BIGINT UNSIGNED NULL, item_type ENUM('process_template','reusable_block','message_template','funnel_template','pipeline_template'), source_entity_id BIGINT UNSIGNED, name VARCHAR(190), slug VARCHAR(190), visibility ENUM('private','account','system') DEFAULT 'account', status ENUM('draft','published','archived') DEFAULT 'draft', created_at DATETIME, updated_at DATETIME);
CREATE TABLE IF NOT EXISTS audit_logs (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, account_id BIGINT UNSIGNED NULL, project_id BIGINT UNSIGNED NULL, user_id BIGINT UNSIGNED NULL, entity_type VARCHAR(64), entity_id BIGINT UNSIGNED NULL, action VARCHAR(64), before_json JSON NULL, after_json JSON NULL, created_at DATETIME);
